const e = $input.item.json;
const ex = e.execution || {};
const wf = e.workflow || {};
const redact = (s) => String(s == null ? '' : s)
  .replace(/access_token=[^&\s"']+/gi, 'access_token=[redacted]')
  .replace(/(bearer|token|authorization|api[_-]?key|secret|password)(["':=\s]+)[A-Za-z0-9._~+\/=-]{8,}/gi, '$1$2[redacted]')
  .replace(/EAA[A-Za-z0-9]{12,}/g, '[redacted]')
  .replace(/\b\d{6,}:[A-Za-z0-9_-]{20,}\b/g, '[redacted]');
const rawMsg = redact((ex.error && ex.error.message) || 'Unknown error').replace(/\s+/g, ' ').trim();
const message = rawMsg.slice(0, 300);
const m = rawMsg.match(/\b(429|5\d{2})\b/);
const transient = !!m || /rate limit|too many requests|timed? ?out|ETIMEDOUT|ECONNRESET|socket hang up/i.test(rawMsg);
let kind = 'permanent';
if (m && m[1] === '429') kind = 'rate_limited_429';
else if (m) kind = 'server_error_' + m[1];
else if (transient) kind = 'network_transient';
return { json: {
  workflow_id: String(wf.id || ''),
  workflow_name: String(wf.name || 'Unknown workflow').slice(0, 120),
  node_name: String(ex.lastNodeExecuted || 'Unknown node').slice(0, 120),
  execution_id: String(ex.id || ''),
  execution_url: String(ex.url || ''),
  error_message: message,
  error_kind: kind,
  transient: transient,
  mode: String(ex.mode || ''),
} };
